package foodchain

import "fmt"

var animals = []struct {
	name  string
	comment string
}{
	{"fly", ""},
	{"spider", "It wriggled and jiggled and tickled inside her."},
	{"bird", "How absurd to swallow a bird!"},
	{"cat", "Imagine that, to swallow a cat!"},
	{"dog", "What a hog, to swallow a dog!"},
	{"goat", "Just opened her throat and swallowed a goat!"},
	{"cow", "I don't know how she swallowed a cow!"},
	{"horse", "She's dead, of course!"},
}

func Verse(v int) string {
	var lines []string
	lines = append(lines, fmt.Sprintf("I know an old lady who swallowed a %s.", animals[v-1].name))
	lines = append(lines, animals[v-1].comment)

	for i := v - 2; i >= 0; i-- {
		if i == 0 {
			lines = append(lines, fmt.Sprintf("She swallowed the %s to catch the fly.", animals[i].name))
		} else {
			lines = append(lines, fmt.Sprintf("She swallowed the %s to catch the %s that wriggled and jiggled and tickled inside her.", animals[i].name, animals[i-1].name))
		}
	}

	lines = append(lines, "I don't know why she swallowed the fly. Perhaps she'll die.")

	out := ""
	for i, line := range lines {
		if i > 0 {
			out += "\n"
		}
		out += line
	}
	return out
}

func Verses(start, end int) string {
	out := ""
	for v := start; v <= end; v++ {
		if v > start {
			out += "\n\n"
		}
		out += Verse(v)
	}
	return out
}

func Song() string {
	return Verses(1, len(animals))
}

